      "js": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>// app.js — ES Modules (\"type\": \"module\" no package.json)\nimport * as readline from \"node:readline/promises\";\nimport { stdin as input, stdout as output } from \"node:process\";\n\nconst rl = readline.createInterface({ input, output });\n\nconst nome = (await rl.question(\"Nome: \")).trim();   // pausa até o Enter\nconst idade = Number.parseInt(await rl.question(\"Idade: \"), 10);\nrl.close();\n\nif (Number.isNaN(idade)) {\n  console.log(\"Idade inválida!\");\n} else {\n  console.log(`Olá, ${nome}! Em 10 anos você terá ${idade + 10} anos.`);\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>node app.js</code> · no navegador use <code>prompt(\"Nome:\")</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "php": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>&lt;?php\n$nome  = trim(readline(\"Nome: \"));   // pausa até o Enter\n$idade = filter_var(readline(\"Idade: \"), FILTER_VALIDATE_INT);\n\nif ($idade === false) {\n    echo \"Idade inválida!\\n\";\n} else {\n    echo \"Olá, $nome! Em 10 anos você terá \" . ($idade + 10) . \" anos.\\n\";\n}\n\n// Sem a extensão readline: $linha = trim(fgets(STDIN));</pre></div><div class=\"rodar\">▶ Rodar: <code>php app.php</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "go": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>package main\n\nimport (\n    \"bufio\"\n    \"fmt\"\n    \"os\"\n    \"strconv\"\n    \"strings\"\n)\n\nfunc main() {\n    leitor := bufio.NewReader(os.Stdin)\n\n    fmt.Print(\"Nome: \")\n    nome, _ := leitor.ReadString('\\n') // lê a linha inteira (com espaços)\n    nome = strings.TrimSpace(nome)\n\n    fmt.Print(\"Idade: \")\n    linha, _ := leitor.ReadString('\\n')\n    idade, err := strconv.Atoi(strings.TrimSpace(linha))\n    if err != nil {\n        fmt.Println(\"Idade inválida!\")\n        return\n    }\n    fmt.Printf(\"Olá, %s! Em 10 anos você terá %d anos.\\n\", nome, idade+10)\n    // fmt.Scanln(&amp;nome) é mais curto, mas para no primeiro espaço\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>go run main.go</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "py": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>nome = input(\"Nome: \").strip()   # pausa até o Enter e devolve str\n\ntry:\n    idade = int(input(\"Idade: \"))\nexcept ValueError:\n    print(\"Idade inválida!\")\nelse:\n    print(f\"Olá, {nome}! Em 10 anos você terá {idade + 10} anos.\")</pre></div><div class=\"rodar\">▶ Rodar: <code>python3 app.py</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "rust": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>use std::io::{self, Write};\n\nfn perguntar(msg: &amp;str) -&gt; String {\n    print!(\"{msg}\");\n    io::stdout().flush().unwrap(); // print! não esvazia o buffer sozinho\n    let mut linha = String::new();\n    io::stdin().read_line(&amp;mut linha).expect(\"falha ao ler\");\n    linha.trim().to_string() // remove o '\\n' do final\n}\n\nfn main() {\n    let nome = perguntar(\"Nome: \");\n    match perguntar(\"Idade: \").parse::&lt;u32&gt;() {\n        Ok(idade) =&gt; println!(\"Olá, {nome}! Em 10 anos você terá {} anos.\", idade + 10),\n        Err(_) =&gt; println!(\"Idade inválida!\"),\n    }\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>cargo run</code> (código em <code>src/main.rs</code>)</div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "c": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n#include &lt;string.h&gt;\n\nint main(void) {\n    char nome[100], linha[32];\n\n    printf(\"Nome: \");\n    if (!fgets(nome, sizeof nome, stdin)) return 1;  // lê a linha (com espaços)\n    nome[strcspn(nome, \"\\n\")] = '\\0';                // remove o '\\n'\n\n    printf(\"Idade: \");\n    if (!fgets(linha, sizeof linha, stdin)) return 1;\n    char *fim;\n    long idade = strtol(linha, &amp;fim, 10);            // fim aponta onde parou\n    if (fim == linha) {\n        printf(\"Idade inválida!\\n\");\n        return 1;\n    }\n    printf(\"Olá, %s! Em 10 anos você terá %ld anos.\\n\", nome, idade + 10);\n    // scanf(\"%99s\", nome) é mais curto, mas para no primeiro espaço\n    return 0;\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>gcc app.c -o app &amp;&amp; ./app</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "cpp": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>#include &lt;iostream&gt;\n#include &lt;string&gt;\n\nint main() {\n    std::string nome;\n    std::cout &lt;&lt; \"Nome: \";\n    std::getline(std::cin, nome);        // lê a linha inteira\n\n    int idade;\n    std::cout &lt;&lt; \"Idade: \";\n    if (!(std::cin &gt;&gt; idade)) {          // falha se não for número\n        std::cout &lt;&lt; \"Idade inválida!\\n\";\n        return 1;\n    }\n    std::cout &lt;&lt; \"Olá, \" &lt;&lt; nome &lt;&lt; \"! Em 10 anos você terá \"\n              &lt;&lt; idade + 10 &lt;&lt; \" anos.\\n\";\n    // cuidado: \"cin &gt;&gt; nome\" para no primeiro espaço\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>g++ -std=c++20 app.cpp -o app &amp;&amp; ./app</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "cs": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>Console.Write(\"Nome: \");\nstring nome = Console.ReadLine()?.Trim() ?? \"\";   // ReadLine pode devolver null\n\nConsole.Write(\"Idade: \");\nif (int.TryParse(Console.ReadLine(), out int idade))\n    Console.WriteLine($\"Olá, {nome}! Em 10 anos você terá {idade + 10} anos.\");\nelse\n    Console.WriteLine(\"Idade inválida!\");</pre></div><div class=\"rodar\">▶ Rodar: <code>dotnet run app.cs</code> (.NET 10) ou no <code>Program.cs</code> de <code>dotnet new console</code></div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
      "java": "<div class=\"codigo\"><button class=\"copiar\" type=\"button\">copiar</button><pre>import java.util.Scanner;\n\npublic class App {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        System.out.print(\"Nome: \");\n        String nome = sc.nextLine().trim();   // lê a linha inteira\n\n        System.out.print(\"Idade: \");\n        try {\n            int idade = Integer.parseInt(sc.nextLine().trim());\n            System.out.printf(\"Olá, %s! Em 10 anos você terá %d anos.%n\", nome, idade + 10);\n        } catch (NumberFormatException e) {\n            System.out.println(\"Idade inválida!\");\n        }\n        // cuidado: nextInt() seguido de nextLine() deixa um '\\n' pendente\n    }\n}</pre></div><div class=\"rodar\">▶ Rodar: <code>java App.java</code> (Java 11+ roda sem compilar antes)</div><div class=\"saida-titulo\">Saída</div><pre class=\"saida\">Nome: Ana Maria Silva\nIdade: 30\nOlá, Ana Maria Silva! Em 10 anos você terá 40 anos.</pre>",
